import React from "react";
import CountUp from "react-countup";

const WordCount = ({ count }) => {
  return (
    <div style={{ fontSize: "2rem", fontWeight: "bold", color: "#007bff" }}>
      <CountUp
        start={0}
        end={count}
        duration={2} // seconds
        separator=","
      />+
    </div>
  );
};

export default WordCount;
